// GetAllProducts is the resolver for the getAllProducts field.
func (r *queryResolver) GetAllProducts(ctx context.Context, query *string, vendorID *string, limit *int32, offset *int32) ([]*model.Product, error) {
	if vendorID == nil || *vendorID == "" {
		return nil, fmt.Errorf("vendorID is required")
	}

	// Defaults
	limitVal := 10
	offsetVal := 0
	if limit != nil {
		limitVal = int(*limit)
	}
	if offset != nil {
		offsetVal = int(*offset)
	}

	// Case 1: Search query is provided
	if query != nil && *query != "" {
		return helper.ExecuteSearchQueryWithVendorPriority(r.DB, *query, *vendorID)
	}

	// Case 2: No query — fetch all by vendor
	return helper.FetchAllProducts(r.DB, limitVal, offsetVal, *vendorID)
}

// GetAllCategories is the resolver for the getAllCategories field.
func (r *queryResolver) GetAllCategories(ctx context.Context, vendorID string) ([]*string, error) {
	// Use a raw SQL query to fetch distinct categories for a specific vendor
	rows, err := r.DB.Raw(`
	SELECT DISTINCT unnest(categories) AS category
	FROM products
	WHERE vendor_id = ? AND categories IS NOT NULL
	`, vendorID).Rows()

	if err != nil {
		return nil, fmt.Errorf("failed to fetch categories: %v", err)
	}
	defer rows.Close()

	var uniqueCategories []string
	for rows.Next() {
		var category string
		if err := rows.Scan(&category); err != nil {
			return nil, fmt.Errorf("failed to scan category: %v", err)
		}
		uniqueCategories = append(uniqueCategories, category)
	}

	// Convert to []*string
	result := make([]*string, len(uniqueCategories))
	for i, category := range uniqueCategories {
		c := category // capture copy
		result[i] = &c
	}

	return result, nil
}

// SearchProducts is the resolver for the searchProducts field.
func (r *queryResolver) SearchProducts(ctx context.Context, query string) ([]*model.Product, error) {
	cleanQuery := helper.CleanSearchQuery(query)

	// Handle empty query
	if cleanQuery == "" {
		return helper.FetchAllProduct(r.DB)
	}

	// Execute search query
	return helper.ExecuteSearchQueryProduct(r.DB, cleanQuery)
}

// GetAllProductsByAdmin is the resolver for the getAllProductsByAdmin field.
func (r *queryResolver) GetAllProductsByAdmin(ctx context.Context) ([]*model.ProductInfor, error) {
	// Get all products
	var products []*model.Product
	if err := r.DB.Order("created_at DESC").Find(&products).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch products: %v", err)
	}

	// Create a map to count the number of items sold for each product
	productSoldCounts := make(map[string]int32)

	// Get all orders with their items
	var orders []*model.Order
	if err := r.DB.Preload("Items").Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch orders: %v", err)
	}

	// Count sold items for each product
	for _, order := range orders {
		for _, item := range order.Items {
			productSoldCounts[item.ProductID] += item.Quantity
		}
	}

	// Create the result array
	result := make([]*model.ProductInfor, 0, len(products))

	// Populate the result with products and their sold counts
	for _, product := range products {
		count := productSoldCounts[product.ID.String()] // Assuming product.ID is uuid.UUID
		info := &model.ProductInfor{
			Product:       product,
			ItemSoldCount: &count,
		}
		result = append(result, info)
	}

	return result, nil
}

